def pancake_sort(arr):
    def flip(sublist, k):
        for i in range((k + 1) // 2):
            sublist[i], sublist[k - i] = sublist[k - i], sublist[i]

    n = len(arr)
    while n > 1:
        for i in range(1, n):
            if arr[i] == max(arr[:n]):
                flip(arr, i)
                flip(arr, n - 1)
                break
        n -= 1
    return arr

